import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { getProgressData } from "@/lib/progress/service";

/**
 * GET /api/v1/progress
 * Returns: verified skills over time, planned versus done minutes per week,
 * MVD streak, evidence mix (E0 to E3 counts), skills due for review,
 * and a plain-language weekly summary generated by code, NOT by AI.
 * Prompt Requirement 4 & 5.
 */
export async function GET(req: NextRequest) {
  const supabase = await createClient();
  const {
    data: { user },
    error: authErr,
  } = await supabase.auth.getUser();

  if (authErr || !user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { searchParams } = new URL(req.url);
  const goalId = searchParams.get("goal_id");

  try {
    const data = await getProgressData(supabase, {
      ownerId: user.id,
      goalId: goalId || undefined,
    });

    return NextResponse.json(data);
  } catch (err: any) {
    return NextResponse.json(
      { error: err.message || "Failed to load progress data" },
      { status: 500 }
    );
  }
}
